package org.sleepwell.app;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public final class MoonSearchStorageTest {
    interface Task{void run(SharedPreferences prefs)throws Exception;}
    void fixture(Task task)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="moon-search-"+UUID.randomUUID();Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());try{task.run(c.getSharedPreferences(name,0));}finally{assertTrue(c.deleteSharedPreferences(name));assertEquals(before,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}}
    @Test public void exactBoardReopensForTheSameOccurrenceAndUnit()throws Exception{fixture(p->{MoonSearch first=MoonSearchState.open(p,"private-run",2,1,new Random(1));MoonSearch reopened=MoonSearchState.open(p,"private-run",2,1,new Random(999));assertEquals(first.encode(),reopened.encode());assertEquals("private-run:2",p.getString("moonSearchOwner",""));MoonSearch following=MoonSearchState.open(p,"private-run",3,2,new Random(3));assertEquals(4,following.columns);assertEquals("private-run:3",p.getString("moonSearchOwner",""));MoonSearch replacement=MoonSearchState.open(p,"new-run",0,0,new Random(4));assertEquals(3,replacement.columns);assertEquals("new-run:0",p.getString("moonSearchOwner",""));});}
    @Test public void corruptOrMismatchedSavedBoardCannotSilentlyRegenerate()throws Exception{fixture(p->{MoonSearchState.open(p,"private-run",0,0,new Random(1));assertTrue(p.edit().putString("moonSearchBoard","invalid").commit());Map<String,?> before=new HashMap<>(p.getAll());assertThrows(IllegalArgumentException.class,()->MoonSearchState.open(p,"private-run",0,0,new Random()));assertEquals(before,p.getAll());MoonSearchState.open(p,"new-run",0,0,new Random(1));before=new HashMap<>(p.getAll());assertThrows(IllegalArgumentException.class,()->MoonSearchState.open(p,"new-run",0,3,new Random()));assertEquals(before,p.getAll());});}
    @Test public void newTaskRoundTripsInExistingRoutineAndBehaviorDefaults()throws Exception{fixture(p->{ChallengeRoutine routine=new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Visual search",3),new ChallengeRoutine.Task("Math",1)));ChallengeRoutine restored=ChallengeRoutineJson.decode(ChallengeRoutineJson.encode(routine));assertEquals(4,restored.units());assertEquals("Visual search",restored.at(2).task.type);assertEquals("Math",restored.at(3).task.type);assertEquals(1,restored.advance(0,0));assertEquals(1,restored.advance(1,0));Alarm a=new Alarm(4);a.setRoutine(restored);Alarm template=AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(a))).create(5);assertEquals("Visual search",template.challenges().tasks.get(0).type);assertEquals(3,template.challenges().tasks.get(0).rounds);assertFalse(template.enabled);assertTrue(template.days.isEmpty());});}
}
